# @url https://codeforces.com/contest/2008/problem/E
# @primary enumeration
# @topics case-analysis, incremental-construction
# @note
# Idea: For even length, independently choose the most frequent character on odd and even positions. For odd length, enumerate the deleted position while maintaining character frequencies on the left and right.
# Key observation: After deleting one character, the parity of every position to its right is reversed, so the resulting odd-position count combines left odd positions with right even positions, and vice versa.
# Complexity: O(26N) time and O(26) space per test case.
# @endnote


import sys

input = sys.stdin.readline


def solve_case():
    n = int(input())
    s = ' ' + input().strip()
    res = 0

    al = [chr(x) for x in range(ord('a'), ord('z') + 1)]

    if n % 2 == 0:
        od = {}
        ev = {}
        for i in range(1, n + 1):
            if i % 2 == 0: ev[s[i]] = ev.get(s[i], 0) + 1
            else : od[s[i]] = od.get(s[i], 0) + 1

        res = n - max(od.values()) - max(ev.values())
    else:
        res = 1e6 
        od = {}
        ev = {}
        for i in range(1, n + 1):
            if i % 2 == 0: ev[s[i]] = ev.get(s[i], 0) + 1
            else : od[s[i]] = od.get(s[i], 0) + 1
        # od ev分别是,奇数位偶数位最多的字母, 且不删
        lfod = {}
        lfev = {}
        # 这两个是从做往右枚举的
        for i in range(1, n + 1):
            # 枚举删第 i 个, 如果要删，带来的影响是后面奇数位偶数位互换

            # 1. 首先把自己删掉
            if i % 2 == 0: ev[s[i]] = max(0, ev.get(s[i], 0) - 1)
            else :         od[s[i]] = max(0, od.get(s[i], 0) - 1)

            res_od, res_ev = {}, {}
            # 2. 算左边和右边的值, 因为奇偶互换了所以左奇数加右偶数,左偶数加右奇数
            for j in al:
                res_ev[j] = lfev.get(j, 0) + od.get(j, 0)
                res_od[j] = lfod.get(j, 0) + ev.get(j, 0)

            # 3. 计算当前删掉 第 i 个 的答案
            res = min(res, n - max(res_od.values()) - max(res_ev.values()))

            #还原
            # 如果删的是 第 i + 1 个，是需要lfod\lfev存档的左, 没有删除的奇偶性是不改变的
            if i % 2 == 0: lfev[s[i]] = lfev.get(s[i], 0) + 1
            else : lfod[s[i]] = lfod.get(s[i], 0) + 1

        res = max(1, res)

    return res



def main():
    t = int(input())

    for _ in range(t):
        print(solve_case())


if __name__ == "__main__":
    main()

# @url https://codeforces.com/contest/2267/problem/D
# @primary sorting-greedy
# @topics sorting-greedy, comparison-sorting, hash-map
# @note
# Idea: Separate values by their original index parity and sort both groups. Construct a candidate sequence by repeatedly taking the smallest available value of the required parity that is at least the previous value; after reaching n, rebuild the remaining values in descending order and continue by taking the largest valid value below the previous one.
# Key observation: Values can only be selected from the parity class required by the current position, so the construction greedily chooses the closest feasible value in the required direction while frequency maps prevent reusing elements.
# Complexity: O(N log N) time and O(N) space per test case.
# @endnote

import sys

input = sys.stdin.readline


def solve_case():
    n = int(input())

    a = [0] + list(map(int, input().strip().split()))
    od = {}
    ev = {}
    odl = []
    evl = []
    m = 1
    for i in range(1, n + 1):
        if i % 2 != 0: 
            od[a[i]] = od.get(a[i], 0) + 1
            odl.append(a[i])
        else: 
            if a[i] == n: m = 2
            evl.append(a[i])
            ev[a[i]] = ev.get(a[i], 0) + 1

    flag = 0

    for i in range(1, n):
        if a[i] < a[i - 1]: flag = 1
    if not flag: return "YES"


    odl = sorted(odl)
    evl = sorted(evl)
    resl = [0]
    flag = 0
    # flag == 0 的时候没有找到 n
    k, j = 0, 0
    cnt = 0
    # 找大的，找小的
    len_evl = len(evl)
    len_odl = len(odl)
    for i in range(1, n + 1):
        if flag == 0:
            if i % 2 == 0:
                while k < len_evl and evl[k] < resl[cnt]: k += 1
                if k < len_evl: 
                    resl.append(evl[k])
                    cnt += 1
                    ev[evl[k]] -= 1 #这个数有没有被用过
                    if evl[k] == n: flag = 1

            else:
                while j < len_odl and odl[j] < resl[cnt]: j += 1
                if j < len_odl: 
                    resl.append(odl[j])
                    cnt += 1
                    od[odl[j]] -= 1
                    if odl[j] == n: flag = 1

        else:
            if flag == 1:
                odll = []
                evll = []
                for ttt in ev:
                    if ev[ttt] > 0: evll.append(ttt)
                for ttt in od:
                    if od[ttt] > 0: odll.append(ttt)
                flag += 1
                k, j = 0, 0
                odll = sorted(odll, reverse=True)
                evll = sorted(evll, reverse=True)
                lk = len(evll)
                lj = len(odll)

                if i % 2 == 0:
                    while k < lk and evll[k] > resl[cnt]: k += 1
                    if k < lk: 
                        resl.append(evll[k])
                        cnt += 1
                else:
                    while j < lj and odll[j] > resl[cnt]: j += 1
                    if j < lj: 
                        resl.append(odll[j])
                        cnt += 1
            else:
                if i % 2 == 0:
                    while k < lk and evll[k] > resl[cnt]: k += 1
                    if k < lk: 
                        resl.append(evll[k])
                        cnt += 1
                else:
                    while j < lj and odll[j] > resl[cnt]: j += 1
                    if j < lj: 
                        resl.append(odll[j])
                        cnt += 1

    if len(resl) - 1 == n: return "YES"
    else: return "NO"
    pass


def main():
    t = int(input())

    for _ in range(t):
        print(solve_case())


if __name__ == "__main__":
    main()

/*
@url https://leetcode.com/problems/car-fleet/
@primary monotonic-stack
@topics comparison-sorting, ordered-map, general-greedy
@note
核心思路：
按照车辆与终点的距离，从最靠近终点的车辆开始向后处理。
每辆车单独到达终点所需时间为 (target - position[i]) / speed[i]。

如果后车的到达时间小于等于前方车队的到达时间，它一定会在终点前
或恰好在终点追上前方车队，因此不会形成新的车队。
只有当前车辆的到达时间严格大于前方最后一个车队的到达时间时，
才会产生一个新的车队。

代码中使用 map 的负位置作为键，使遍历顺序从位置最大到位置最小。
到达时间形成单调序列；由于这里只需要统计车队数量，所以不需要保存
完整的单调栈，只需要保存当前最后一个车队的到达时间 cur。

复杂度：
时间复杂度 O(n log n)，其中排序由 map 完成。
空间复杂度 O(n)。

复习重点：
1. 必须从最靠近终点的车辆向后判断。
2. 相同到达时间属于同一个车队，所以只有 time > cur 时答案才加一。
3. 这道题虽然代码没有显式使用 stack，但本质是 Monotonic Stack 模型。
@endnote
*/

#include <map>
#include <vector>
using namespace std;

class Solution {
public:
    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        map<int, double> cars;

        const int n = static_cast<int>(position.size());
        for (int i = 0; i < n; ++i) {
            cars[-position[i]] =
                static_cast<double>(target - position[i]) / speed[i];
        }

        int fleets = 0;
        double latestArrivalTime = 0.0;

        for (const auto& [negativePosition, arrivalTime] : cars) {
            (void)negativePosition;
            if (arrivalTime > latestArrivalTime) {
                latestArrivalTime = arrivalTime;
                ++fleets;
            }
        }

        return fleets;
    }
};

/*
@url https://leetcode.com/problems/min-stack/
@primary stack
@topics array, implementation
@note
核心思路：
栈中的每个元素同时保存两个值：
1. 当前压入的实际数值。
2. 从栈底到当前位置为止的最小值。

push 时，新位置的最小值等于 min(val, 之前的最小值)。
pop 时，数值和对应的最小值一起删除。
因此 top 和 getMin 都只需要访问最后一个元素，不需要重新遍历整个栈。

状态表示：
st[i][0] 表示第 i 个元素的实际值。
st[i][1] 表示包含第 i 个元素在内的整个栈的最小值。

复杂度：
push、pop、top、getMin 的时间复杂度均为 O(1)。
保存 n 个元素的空间复杂度为 O(n)。

复习重点：
把需要快速查询的历史状态与每个栈元素一起保存。
这是典型的“辅助状态随主状态同步入栈和出栈”模型。
@endnote
*/

#include <algorithm>
#include <array>
#include <vector>
using namespace std;

class MinStack {
private:
    vector<array<int, 2>> st;

public:
    MinStack() = default;

    void push(int val) {
        const int minimum = st.empty() ? val : min(val, st.back()[1]);
        st.push_back({val, minimum});
    }

    void pop() {
        st.pop_back();
    }

    int top() {
        return st.back()[0];
    }

    int getMin() {
        return st.back()[1];
    }
};
